INSERT INTO lessons (title,level,category,duration,lesson_order) SELECT x.title,x.level,x.category,x.duration,x.ord FROM jsonb_to_recordset('[{"title":"What is Graphic Design?","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":1},{"title":"Elements of Design","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":2},{"title":"Principles of Design","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":3},{"title":"Colour Theory","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":4},{"title":"Typography","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":5},{"title":"Composition","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":6},{"title":"Layout","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":7},{"title":"Visual Hierarchy","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":8},{"title":"Contrast","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":9},{"title":"Balance","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":10},{"title":"Alignment","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":11},{"title":"Spacing","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":12},{"title":"Grids","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":13},{"title":"White Space","level":"Beginner","category":"Fundamentals","duration":"20 min","ord":14},{"title":"Branding Basics","level":"Intermediate","category":"Branding","duration":"25 min","ord":15},{"title":"Logo Design","level":"Intermediate","category":"Branding","duration":"25 min","ord":16},{"title":"Brand Identity","level":"Intermediate","category":"Branding","duration":"25 min","ord":17},{"title":"Social Media Design","level":"Intermediate","category":"Marketing Design","duration":"25 min","ord":18},{"title":"Poster Design","level":"Intermediate","category":"Marketing Design","duration":"25 min","ord":19},{"title":"Advertisement Design","level":"Intermediate","category":"Marketing Design","duration":"25 min","ord":20},{"title":"Marketing Design","level":"Intermediate","category":"Marketing Design","duration":"25 min","ord":21},{"title":"Design Psychology","level":"Intermediate","category":"Design Thinking","duration":"25 min","ord":22},{"title":"Understanding Client Briefs","level":"Intermediate","category":"Design Thinking","duration":"25 min","ord":23},{"title":"Design Problem Solving","level":"Intermediate","category":"Design Thinking","duration":"25 min","ord":24},{"title":"Brand Strategy","level":"Advanced","category":"Strategy","duration":"30 min","ord":25},{"title":"Art Direction","level":"Advanced","category":"Strategy","duration":"30 min","ord":26},{"title":"Design Systems","level":"Advanced","category":"Systems","duration":"30 min","ord":27},{"title":"Campaign Design","level":"Advanced","category":"Strategy","duration":"30 min","ord":28},{"title":"Creative Strategy","level":"Advanced","category":"Strategy","duration":"30 min","ord":29},{"title":"Professional Brand Projects","level":"Advanced","category":"Projects","duration":"30 min","ord":30}]'::jsonb) AS x(title text,level text,category text,duration text,ord int);
INSERT INTO tools (name,pricing,level,category,description,best_for,url) SELECT x.name,x.pricing,x.level,x.category,x.description,x.best_for,x.url FROM jsonb_to_recordset('[{"name":"Canva","pricing":"Freemium","level":"Beginner","category":"Social Media","description":"Fast visual design with templates and brand tools.","best_for":"Social posts, presentations, simple marketing","url":"https://www.canva.com/"},{"name":"Photopea","pricing":"Free","level":"Beginner","category":"Photo Editing","description":"Browser-based image editor with Photoshop-style workflows.","best_for":"Photo editing, PSD files, quick edits","url":"https://www.photopea.com/"},{"name":"Figma","pricing":"Freemium","level":"Beginner","category":"UI/UX","description":"Collaborative interface and design tool for digital products.","best_for":"UI design, wireframes, prototypes","url":"https://www.figma.com/"},{"name":"GIMP","pricing":"Free","level":"Intermediate","category":"Photo Editing","description":"Open-source raster image editor.","best_for":"Photo editing, image manipulation","url":"https://www.gimp.org/"},{"name":"Inkscape","pricing":"Free","level":"Intermediate","category":"Illustration","description":"Open-source vector graphics editor.","best_for":"Vector artwork, illustrations, logos","url":"https://inkscape.org/"},{"name":"Krita","pricing":"Free","level":"Beginner","category":"Illustration","description":"Digital painting and illustration software.","best_for":"Digital art, illustration, concept work","url":"https://krita.org/"},{"name":"Adobe Photoshop","pricing":"Paid","level":"Beginner","category":"Photo Editing","description":"Professional raster editor for images and compositing.","best_for":"Photo manipulation, posters, advertising","url":"https://www.adobe.com/products/photoshop.html"},{"name":"Adobe Illustrator","pricing":"Paid","level":"Intermediate","category":"Logo Design","description":"Professional vector design software.","best_for":"Logos, icons, illustration, branding","url":"https://www.adobe.com/products/illustrator.html"},{"name":"Adobe InDesign","pricing":"Paid","level":"Intermediate","category":"Print Design","description":"Layout software for multi-page publications.","best_for":"Menus, brochures, magazines, print","url":"https://www.adobe.com/products/indesign.html"},{"name":"Affinity","pricing":"Paid","level":"Intermediate","category":"Graphic Design","description":"Professional creative software for vector, photo and layout work.","best_for":"Branding, illustration, publishing","url":"https://affinity.serif.com/"}]'::jsonb) AS x(name text,pricing text,level text,category text,description text,best_for text,url text);
INSERT INTO resources (name,category,pricing,description,url) SELECT x.name,x.category,x.pricing,x.description,x.url FROM jsonb_to_recordset('[{"name":"Behance","category":"Inspiration","pricing":"Free","description":"Discover portfolios and professional creative work.","url":"https://www.behance.net/"},{"name":"Dribbble","category":"Inspiration","pricing":"Free","description":"Explore visual design work and creative ideas.","url":"https://dribbble.com/"},{"name":"Pinterest","category":"Inspiration","pricing":"Free","description":"Build visual references and moodboards.","url":"https://www.pinterest.com/"},{"name":"Awwwards","category":"Inspiration","pricing":"Free","description":"Explore standout digital and web design.","url":"https://www.awwwards.com/"},{"name":"Google Fonts","category":"Fonts","pricing":"Free","description":"Free, open-source font collection for design projects.","url":"https://fonts.google.com/"},{"name":"Fontshare","category":"Fonts","pricing":"Free","description":"Curated free fonts for modern design work.","url":"https://www.fontshare.com/"},{"name":"DaFont","category":"Fonts","pricing":"Free","description":"Large directory of downloadable fonts.","url":"https://www.dafont.com/"},{"name":"Coolors","category":"Colours","pricing":"Freemium","description":"Generate and explore colour palettes.","url":"https://coolors.co/"},{"name":"Adobe Color","category":"Colours","pricing":"Free","description":"Create colour themes and explore colour relationships.","url":"https://color.adobe.com/"},{"name":"Color Hunt","category":"Colours","pricing":"Free","description":"Browse curated colour palettes.","url":"https://colorhunt.co/"},{"name":"Unsplash","category":"Images","pricing":"Free","description":"High-quality stock photography.","url":"https://unsplash.com/"},{"name":"Pexels","category":"Images","pricing":"Free","description":"Free stock photos and videos.","url":"https://www.pexels.com/"},{"name":"Pixabay","category":"Images","pricing":"Free","description":"Free images, illustrations and media.","url":"https://pixabay.com/"},{"name":"Flaticon","category":"Icons","pricing":"Freemium","description":"Large library of icons and vector assets.","url":"https://www.flaticon.com/"},{"name":"Lucide","category":"Icons","pricing":"Free","description":"Open-source icon library for modern interfaces.","url":"https://lucide.dev/"},{"name":"Material Icons","category":"Icons","pricing":"Free","description":"Google icon library for interface design.","url":"https://fonts.google.com/icons"},{"name":"Mockup World","category":"Mockups","pricing":"Free","description":"Collection of mockup resources for presentations.","url":"https://www.mockupworld.co/"},{"name":"LS Graphics","category":"Mockups","pricing":"Freemium","description":"Premium and free mockups for branding and digital work.","url":"https://www.ls.graphics/"}]'::jsonb) AS x(name text,category text,pricing text,description text,url text);
INSERT INTO tutorials (title,channel,duration,level,software,url) SELECT x.title,x.channel,x.duration,x.level,x.software,x.url FROM jsonb_to_recordset('[{"title":"Photoshop for Beginners — Full Course","channel":"PiXimperfect","duration":"1h 20m","level":"Beginner","software":"Photoshop","url":"https://www.youtube.com/results?search_query=Photoshop+for+beginners+PiXimperfect"},{"title":"Photoshop Poster Design for Beginners","channel":"Satori Graphics","duration":"25 min","level":"Beginner","software":"Photoshop","url":"https://www.youtube.com/results?search_query=Photoshop+poster+design+Satori+Graphics"},{"title":"Illustrator Logo Design Tutorial","channel":"Satori Graphics","duration":"20 min","level":"Beginner","software":"Illustrator","url":"https://www.youtube.com/results?search_query=Illustrator+logo+design+Satori+Graphics"},{"title":"Canva Graphic Design Tutorial","channel":"Canva","duration":"30 min","level":"Beginner","software":"Canva","url":"https://www.youtube.com/results?search_query=Canva+graphic+design+tutorial"},{"title":"Figma UI Design for Beginners","channel":"Figma","duration":"35 min","level":"Beginner","software":"Figma","url":"https://www.youtube.com/results?search_query=Figma+UI+design+for+beginners"},{"title":"Typography Basics for Designers","channel":"The Futur","duration":"18 min","level":"Beginner","software":"Design Theory","url":"https://www.youtube.com/results?search_query=The+Futur+typography+basics"},{"title":"Colour Theory for Designers","channel":"The Futur","duration":"22 min","level":"Beginner","software":"Design Theory","url":"https://www.youtube.com/results?search_query=The+Futur+colour+theory+designers"},{"title":"Brand Identity Design Process","channel":"The Futur","duration":"40 min","level":"Intermediate","software":"Branding","url":"https://www.youtube.com/results?search_query=The+Futur+brand+identity+design+process"}]'::jsonb) AS x(title text,channel text,duration text,level text,software text,url text);